// UTM 18N metres: resample every track to a 60 s clock, then find pairs within 200 m.
graph.add(
  new GPUTrajectoryResample({
    ...tracks,
    sampleCount: bucketCount,
    spacing: 'clock',
    clock,
    output: {samples}
  })
);
graph.add(
  new GPUTrajectoryEncounters({
    samples,
    trackCount,
    bucketCount,
    distance,
    cellSize: 250,
    bounds,
    hitCapacity: 1 << 16,
    output
  })
);
const {pairs} = output;
